// Vite-only loader for the committed policy wasm.
//
// This file is kept out of lib/policy.js so the adapter stays importable by
// plain Node (the node tests never need wasm). The artifact is generated by
// crates/tunlion-policy-wasm/build-wasm.sh and committed under
// frontend/src/policy/ by CI (.github/workflows/policy-wasm.yml). See
// frontend/src/policy/README.md.
//
// The globs resolve to an empty object until the artifact is committed, so a
// plain `npm run build` still works and every decision fails closed until then.

const bindings = import.meta.glob('../policy/tunlion_policy_wasm.js', { eager: true })
const wasmUrls = import.meta.glob('../policy/tunlion_policy_wasm_bg.wasm', {
  eager: true,
  query: '?url',
  import: 'default',
})

let loaded = null

/// Initialize the wasm once and return its one export. Throws a descriptive
/// error when the committed artifact is absent; callers turn that into a denial.
export function initPolicyWasm() {
  if (loaded) return loaded
  loaded = (async () => {
    // The patterns are exact, so each map has at most one entry. Reading the
    // value avoids depending on how Vite spells the relative key.
    const mod = Object.values(bindings)[0]
    const wasmUrl = Object.values(wasmUrls)[0]
    if (!mod || !wasmUrl) {
      throw new Error(
        'policy wasm is not committed under frontend/src/policy; run the Browser policy wasm workflow and commit its artifact',
      )
    }
    await mod.default({ module_or_path: wasmUrl })
    return mod.admitTransfer
  })()
  return loaded
}
